command:
RES=$(curl -sS -X POST \
  -H "Accept: application/json" \
  -H "Content-Type: application/json" \
  -H "Authorization: SSWS $OKTA_API_TOKEN" \
  -d '{"profile": {"name": "${answer1}", "description": "${answer2}"}}' \
  "$OKTA_URL/api/v1/groups") ; \
echo "$RES" | python3 -c '
import sys, os, json, subprocess
text = sys.stdin.read().strip()
try:
    data = json.loads(text)
except:
    data = {}
if isinstance(data, dict) and "id" in data:
    print(json.dumps(data))
elif "already exists" in text.lower():
    name = """${answer1}""".strip()
    token = os.environ.get("OKTA_API_TOKEN", "")
    okta_url = os.environ.get("OKTA_URL", "").rstrip("/")
    cmd = ["curl", "-sS", "-G", f"{okta_url}/api/v1/groups", "-H", f"Authorization: SSWS {token}", "-H", "Accept: application/json", "--data-urlencode", f"q={name}"]
    r = subprocess.run(cmd, capture_output=True, text=True)
    try:
        groups = json.loads(r.stdout)
        match = next((g for g in groups if g.get("profile", {}).get("name", "").strip().lower() == name.lower()), groups[0] if groups else None)
        if match:
            print(json.dumps(match))
        else:
            print(text)
    except:
        print(text)
else:
    print(text)
'
